{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "陈江",
      "role": "protagonist",
      "identity": "1992年活跃于南北线路的个体户倒爷，有一辆嘉陵70摩托带边斗",
      "traits": ["豪爽不羁", "心思细腻", "敢闯敢拼", "嘴硬心软"],
      "overt_motivation": "从南方进电子表运到北方售卖，赚一笔钱还债",
      "covert_motivation": "策划一场七天七夜的流浪婚礼，向暗恋已久的苏晓求婚",
      "secret_fear": "怕苏晓嫌弃自己没稳定工作，怕求婚被拒绝后连朋友都做不成",
      "misperception_of_other": "以为苏晓只是为了赚工钱才跟着自己跑货，不知道苏晓也喜欢自己"
    },
    {
      "name": "苏晓",
      "role": "deuteragonist",
      "identity": "原国营纺织厂女工，1992年下岗待业",
      "traits": ["温婉沉静", "倔强有主见", "细心敏感", "重情重义"],
      "overt_motivation": "跟着陈江押货，赚50块工钱补贴家用",
      "covert_motivation": "想和暗恋的陈江多待一段时间，看看两人有没有未来的可能",
      "secret_fear": "怕陈江只是把自己当临时雇工，怕自己下岗的身份配不上走南闯北的陈江",
      "misperception_of_other": "以为陈江只是缺个押货的人手才找自己，不知道陈江暗恋自己很久了"
    }
  ],
  "supporting_characters": [
    {
      "name": "李建国",
      "function": "反转点",
      "identity": "北方运输公司的大货车司机",
      "description": "连夜跑长途疲劳驾驶，最后在县城路口撞到了去买车票的陈江"
    }
  ],
  "relationship_dynamics": "陈江和苏晓是住同一个大院的邻居，认识三年互有好感但都没捅破窗户纸。初期是雇主和雇工的关系，一路同行互相照顾，关系逐渐升温，旅途最后两天互明心意，约定一起去深圳打拼，就在最幸福的时刻陈江遭遇车祸去世，苏晓带着两人的回忆独自去了深圳，终身未婚。"
}"}

